mapper.select:
select t.id, t.stock_name, t.stock_code, t.rise_fall_prediction, t.prediction_time, t.prediction_content, t.prediction_basis, t.basis_type, t.rise_fall_result, t.actual_content, t.result_analysis, t.prediction_situation, t.prediction_result, t.simulate_operation, t.trade_share, t.current_price, t.handling_fee, t.trade_status, t.owner, t.create_time, t.update_time from t_trial_prediction t
and t.stock_name like concat('%', #{stockName}, '%')
and t.stock_code like concat('%', #{stockCode}, '%')
and t.rise_fall_prediction in
#{item}
and (
FIND_IN_SET(#{item}, t.basis_type) > 0
)
and t.prediction_time >= #{predictionTimeStart}
and t.prediction_time <= #{predictionTimeEnd}
and t.prediction_situation in
#{item}
and t.prediction_result in
#{item}
and t.simulate_operation in
#{item}
and t.trade_status in
#{item}
and t.owner = #{owner}
order by t.create_time desc

select count(*) from t_trial_prediction t


        and t.prediction_time >= #{startTime}


        and t.prediction_time <= #{endTime}


        and (

            FIND_IN_SET(#{item}, t.basis_type) > 0

        )


        and t.stock_code like concat('%', #{stockCode}, '%')


        and t.owner = #{owner}

select count(*) from t_trial_prediction t

    t.prediction_result = 1

        and t.prediction_time >= #{startTime}


        and t.prediction_time <= #{endTime}


        and (

            FIND_IN_SET(#{item}, t.basis_type) > 0

        )


        and t.stock_code like concat('%', #{stockCode}, '%')


        and t.owner = #{owner}

select t.basis_type as basisType,
       count(*) as count,
       sum(case when t.prediction_result = 1 then 1 else 0 end) as successCount
from t_trial_prediction t


        and t.prediction_time >= #{startTime}


        and t.prediction_time <= #{endTime}


        and (

            FIND_IN_SET(#{item}, t.basis_type) > 0

        )


        and t.stock_code like concat('%', #{stockCode}, '%')


        and t.owner = #{owner}


group by t.basis_type
order by t.basis_type asc

select t.prediction_situation as predictionSituation,
       count(*) as count
from t_trial_prediction t

    t.prediction_situation is not null

        and t.prediction_time >= #{startTime}


        and t.prediction_time <= #{endTime}


        and (

            FIND_IN_SET(#{item}, t.basis_type) > 0

        )


        and t.stock_code like concat('%', #{stockCode}, '%')


        and t.owner = #{owner}


group by t.prediction_situation
order by t.prediction_situation asc

select date_format(t.prediction_time, '%Y-%m') as month,
       count(*) as totalCount,
       sum(case when t.prediction_result = 1 then 1 else 0 end) as successCount
from t_trial_prediction t


        and t.prediction_time >= #{startTime}


        and t.prediction_time <= #{endTime}


        and (

            FIND_IN_SET(#{item}, t.basis_type) > 0

        )


        and t.stock_code like concat('%', #{stockCode}, '%')


        and t.owner = #{owner}


group by date_format(t.prediction_time, '%Y-%m')
order by month asc

select sum(case when t.simulate_operation = 1 then 1 else 0 end) as totalBuyCount, sum(case when t.simulate_operation = 2 then 1 else 0 end) as totalSellCount, ifnull(sum(case when t.simulate_operation = 1 then t.trade_share * t.current_price else 0 end), 0) as totalBuyAmount, ifnull(sum(case when t.simulate_operation = 2 then t.trade_share * t.current_price else 0 end), 0) as totalSellAmount, ifnull(sum(t.handling_fee), 0) as totalHandlingFee from t_trial_prediction t
t.simulate_operation is not null
and t.prediction_time >= #{startTime}
and t.prediction_time <= #{endTime}
and (
FIND_IN_SET(#{item}, t.basis_type) > 0
)
and t.stock_code like concat('%', #{stockCode}, '%')
and t.owner = #{owner}

select t.stock_name as stockName, t.stock_code as stockCode, count(*) as predictCount, sum(case when t.prediction_result = 1 then 1 else 0 end) as successCount from t_trial_prediction t
and t.prediction_time >= #{startTime}
and t.prediction_time <= #{endTime}
and (
FIND_IN_SET(#{item}, t.basis_type) > 0
)
and t.stock_code like concat('%', #{stockCode}, '%')
and t.owner = #{owner}
group by t.stock_code, t.stock_name order by predictCount desc

select t.id, t.stock_name, t.stock_code, t.rise_fall_prediction, t.prediction_time, t.prediction_content, t.prediction_basis, t.basis_type, t.rise_fall_result, t.actual_content, t.result_analysis, t.prediction_situation, t.prediction_result, t.simulate_operation, t.trade_share, t.current_price, t.handling_fee, t.trade_status, t.owner, t.create_time, t.update_time from t_trial_prediction t
and t.prediction_time >= #{startTime}
and t.prediction_time <= #{endTime}
and (
FIND_IN_SET(#{item}, t.basis_type) > 0
)
and t.stock_code like concat('%', #{stockCode}, '%')
and t.owner = #{owner}
and t.prediction_result = #{predictionResult}
and t.prediction_situation = #{predictionSituation}
and t.simulate_operation = #{simulateOperation}
and date_format(t.prediction_time, '%Y-%m') = #{month}
and t.stock_code = #{detailStockCode}
order by t.prediction_time desc
